uses {IO}
import IO
import String
import List
import Map

let first_part sep s = List.head! (String.split sep s)

-- Some host for a valid line, None otherwise
let host_of line =
  let rest =
    if String.starts_with? "https://" line then Some (String.slice 8 (String.length line) line)
    else if String.starts_with? "http://" line then Some (String.slice 7 (String.length line) line)
    else None
  match rest with
  | None -> None
  | Some r ->
    let h = String.lower (first_part ":" (first_part "#" (first_part "?" (first_part "/" r))))
    if String.empty? h then None else Some h

let lines = String.lines (IO.read_all! ()) |> List.map String.trim |> List.filter (fn l -> !(String.empty? l))
let hosts = List.filter_map host_of lines
let bad = List.length lines - List.length hosts
let rows = Map.to_list (List.tally hosts) |> List.sort_by (fn p -> (0 - p.1, p.0))
List.each (fn p -> IO.println "%{p.1} %{p.0}") rows
if bad > 0 then IO.println "%{bad} invalid" else ()
EOF
