uses {IO, Proc}
import IO
import String
import List
import Map
import Regex
import Int

let line_re = r/^([^ ]+) +((?:[0-9]+h)?(?:[0-9]+m)?(?:[0-9]+s)?)$/
let part_re = r/^(?:([0-9]+)h)?(?:([0-9]+)m)?(?:([0-9]+)s)?$/

let num s = if String.empty? s then 0 else Int.of_string! s

let fmt t =
  let h = t / 3600;
  let m = (t % 3600) / 60;
  let s = t % 60;
  let out = (if h > 0 then "%{h}h" else "") ++ (if m > 0 then "%{m}m" else "") ++ (if s > 0 then "%{s}s" else "");
  if String.empty? out then "0s" else out

let parse line =
  let c = Regex.capture line_re line;
  match c with
  | [_, name, d] ->
    if String.empty? d then None else
    match Regex.capture part_re d with
    | [_, h, m, s] -> Some (name, num h * 3600 + num m * 60 + num s)
    | _ -> None
  | _ -> None

let lines = List.indexed (List.map String.trim (Stream.to_list (IO.stdin_lines ())))
EOF
