import IO
import Regex
import String
import List
import Map
import Int
import Proc

let num s = if s == "" then 0 else Int.of_string! s

let parse line =
  let t = String.trim line;
  let c = Regex.capture r/^([^ \t]+) +(?:([0-9]+)h)?(?:([0-9]+)m)?(?:([0-9]+)s)?$/ t;
  match c with
  | [_, name, h, m, s] ->
    if name == "total" || (h == "" && m == "" && s == "") then None
    else Some (name, num h * 3600 + num m * 60 + num s)
  | _ -> None

let fmt n =
  let h = n / 3600;
  let m = (n % 3600) / 60;
  let s = n % 60;
  let out = (if h > 0 then "%{h}h" else "") ++ (if m > 0 then "%{m}m" else "") ++ (if s > 0 then "%{s}s" else "");
  if out == "" then "0s" else out

let lines = IO.stdin_lines () |> Stream.to_list
let parsed = List.indexed lines |> List.filter (fn p -> String.trim p.1 != "") |> List.map (fn p -> (p.0 + 1, parse p.1))
let bad = List.find (fn p -> p.1 == None) parsed

match bad with
| Some p ->
  IO.println_err "line %{p.0}: invalid line"
  Proc.exit 1
| None ->
  let totals = List.fold_left (fn m p -> match p.1 with
    | Some (n, v) -> Map.update n 0 (fn x -> x + v) m
    | None -> m) Map.empty parsed;
  let names = List.sort (Map.keys totals);
  List.each (fn n -> IO.println "%{n} %{fmt (Map.get! n totals)}") names
  IO.println "total %{fmt (List.sum (Map.values totals) |> Option.default 0)}"
EOF
