uses {IO}
import IO
import List
import String
import Map
import Decode

let rec_dec = Decode.map2 (fn e m -> (e, m)) (Decode.field "endpoint" Decode.string) (Decode.field "ms" Decode.int)

let parse line =
  match Decode.run rec_dec line with
  | Ok (e, m) -> if m >= 0 then Some (e, m) else None
  | Error _ -> None

let pct vs p =
  let n = List.length vs;
  let r = (p * n + 99) / 100;
  List.get! (r - 1) vs

let lines = IO.stdin_lines () |> List.filter (fn l -> !(String.empty? (String.trim l)))
let parsed = List.map parse lines
let good = List.filter_map (fn x -> x) parsed
let skipped = List.length parsed - List.length good
let groups = List.fold_left (fn acc (e, m) -> Map.update e (fn o -> match o with | Some l -> Some (m :: l) | None -> Some [m]) acc) Map.empty good
let keys = List.sort (Map.keys groups)
List.each (fn k -> let vs = List.sort (Map.get! k groups); IO.println "%{k} count=%{List.length vs} p50=%{pct vs 50} p95=%{pct vs 95}") keys
if skipped > 0 then IO.println "skipped %{skipped}" else ()
EOF
