cat > solution.wand <<'EOF'
uses {IO}
import IO
import Decode
import Stream
import Map
import List
import String

let dec = Decode.map2 (fn e m -> (e, m)) (Decode.field "endpoint" Decode.string) (Decode.field "ms" Decode.int)

let step acc line =
  if String.empty? (String.trim line) then acc
  else
    match Decode.run dec line with
    | Ok (e, m) ->
      if m >= 0 then
        (Map.update e (fn o -> match o with
          | Some l -> Some (m :: l)
          | None -> Some [m]) acc.0, acc.1)
      else (acc.0, acc.1 + 1)
    | Error _ -> (acc.0, acc.1 + 1)

let pct sorted n p =
  let r = (p * n + 99) / 100;
  match List.get (r - 1) sorted with
  | Some v -> v
  | None -> 0

let (groups, skipped) = IO.stdin_lines () |> Stream.fold_left step (Map.empty, 0)

let eps = List.sort_by (fn e -> e) (Map.keys groups)
List.each (fn e ->
  let vs = List.sort_by (fn x -> x) (Map.get! e groups);
  let n = List.length vs;
  IO.println "%{e} count=%{n} p50=%{pct vs n 50} p95=%{pct vs n 95}") eps
if skipped > 0 then IO.println "skipped %{skipped}" else ()
EOF
